/**
 * Query helper for instant O(1) textbook question bank lookup
 */
export function queryMasterQuestionBank(classNum, subject, chapterNum) {
  const cKey = String(classNum || '8').replace('Class ', '').trim();
  const sKey = String(subject || '').toLowerCase().includes('sci') ? 'science' :
               String(subject || '').toLowerCase().includes('math') ? 'mathematics' :
               String(subject || '').toLowerCase().includes('soc') || String(subject || '').toLowerCase().includes('sst') ? 'social_science' :
               String(subject || '').toLowerCase().includes('hin') ? 'hindi' :
               String(subject || '').toLowerCase().includes('eng') ? 'english' :
               String(subject || '').toLowerCase().includes('san') ? 'sanskrit' : null;
  if (!sKey || !DAV_MASTER_QUESTION_BANK[cKey]?.[sKey]) return null;
  const chapters = DAV_MASTER_QUESTION_BANK[cKey][sKey].chapters;
  if (!chapterNum) return chapters;
  return chapters.find(ch => ch.chapterNumber === Number(chapterNum)) || chapters[0] || null;
}
